<template>
  <div class="chat-page">
    <div class="chat-head"><div><span class="eyebrow">AI OPERATIONS COPILOT</span><h2>智能运维对话</h2><p>连接企业知识库，查询当前状态、解释告警并给出符合公司规则的处理建议。</p></div><div class="ai-status"><span />{{ statusText }}</div></div>
    <div class="chat-layout">
      <section class="chat-card"><div ref="messageBox" class="message-box"><div v-if="!messages.length" class="welcome"><div class="bot-mark"><el-icon><Monitor /></el-icon></div><h3>你好，我是新知AI-智能巡检</h3><p>{{ dataMode ? '我可以直接查询业务数据库（只读），回答例如：' : '我可以基于企业运维知识和实时状态，回答例如：' }}</p><div class="suggestions"><button v-for="item in activeSuggestions" :key="item" @click="send(item)">{{ item }}<el-icon><ArrowRight /></el-icon></button></div></div><div v-for="item in messages" :key="item.id" class="message" :class="item.role"><div class="message-avatar">{{ item.role === 'assistant' ? 'AI' : '我' }}</div><div class="message-content"><div class="message-meta">{{ item.role === 'assistant' ? '新知AI-智能巡检' : '我' }}<small v-if="item.source">· {{ item.source === 'ai' ? '企业模型' : '状态兜底' }}</small></div><div class="message-text">{{ item.content }}</div><div v-if="item.data" class="data-block"><div class="data-meta">查询到 {{ item.data.row_count }} 行（最多展示 {{ item.data.rows.length }} 行）</div><el-table :data="item.data.rows" size="small" max-height="240" class="data-table"><el-table-column v-for="(col, i) in item.data.columns" :key="col + i" :prop="String(i)" :label="col" min-width="110" show-overflow-tooltip /></el-table><details class="sql-detail"><summary>执行的只读 SQL（安全审计通过）</summary><code>{{ item.data.sql }}</code></details></div><div v-if="item.knowledge?.length" class="citation"><el-icon><Collection /></el-icon>参考 {{ item.knowledge.length }} 条知识：{{ item.knowledge.map((row) => row.title).join('、') }}</div></div></div><div v-if="sending && !receiving" class="message assistant"><div class="message-avatar">AI</div><div class="message-content"><div class="message-meta">新知AI-智能巡检</div><div class="typing"><i /><i /><i /></div></div></div></div><div class="quick-bar"><span>快捷提问</span><button v-for="item in activeSuggestions.slice(0, 3)" :key="item" @click="send(item)">{{ item }}</button><span class="mode-switch"><el-switch v-model="dataMode" size="small" />数据问答<small>直连业务库（只读）</small></span></div><div class="composer"><el-input v-model="draft" type="textarea" :autosize="{ minRows: 2, maxRows: 6 }" maxlength="4000" show-word-limit :placeholder="dataMode ? '用自然语言查询业务数据，如：每个负责人名下有多少台子机？' : '描述你的运维问题，或询问当前服务器状态...'" @keydown.enter.exact.prevent="send()" /><el-button type="primary" :loading="sending" :disabled="!draft.trim()" @click="send()"><el-icon><Promotion /></el-icon>发送</el-button></div><div class="composer-tip">Enter 发送 · Shift + Enter 换行 · AI 仅做分析与建议，涉及变更仍需人工确认</div></section>
      <aside class="context-card"><div class="context-title">实时运维上下文 <span class="live"><i />LIVE</span></div><div class="context-kpis"><div><strong>{{ runtime?.assets?.total ?? '—' }}</strong><span>资产总数</span></div><div><strong class="green">{{ runtime?.assets?.reachable ?? '—' }}</strong><span>可达资产</span></div><div><strong class="orange">{{ runtime?.active_anomalies?.length ?? '—' }}</strong><span>活动异常</span></div><div><strong class="violet">{{ runtime?.open_ticket_count ?? '—' }}</strong><span>未关闭任务</span></div></div><div class="context-section"><div class="section-label">当前异常</div><div v-if="runtime?.active_anomalies?.length" v-for="item in runtime.active_anomalies" :key="item.host + item.trigger" class="context-alert"><span /><div><strong>{{ item.host || '未知主机' }}</strong><small>{{ item.trigger || item.message }}</small></div></div><el-empty v-else description="当前无活动异常" :image-size="46" /></div><div class="context-section"><div class="section-label">使用说明</div><ul><li>回答优先参考企业上传的运维规则</li><li>状态信息来自平台当前数据库快照</li><li>不会向模型发送密码、Token 或私钥</li></ul></div></aside>
    </div>
  </div>
</template>

<script setup>
import { computed, nextTick, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { sendDataQuery, streamKnowledgeChat } from '../api'
import { createTyper } from '../composables/typewriter'

const draft = ref(''); const sending = ref(false); const receiving = ref(false); const messages = ref([]); const messageBox = ref(null); const runtime = ref(null); const dataMode = ref(false)
const suggestions = ['当前服务器整体状态怎么样？', '请分析最近的活动告警并给出处理建议', '公司磁盘告警的标准处置规则是什么？', '哪些任务单还没有闭环？']
const dataSuggestions = ['现在有多少台资产？母机和子机各多少？', '当前各严重级别的异常告警有多少？', '每个负责人名下有多少台机器？', '最近的 AI 分析结论有哪些？']
const activeSuggestions = computed(() => (dataMode.value ? dataSuggestions : suggestions))
const statusText = computed(() => sending.value ? '正在分析' : 'AI 已就绪')
async function scrollBottom() { await nextTick(); if (messageBox.value) messageBox.value.scrollTop = messageBox.value.scrollHeight }
async function send(text = '') { const value = (text || draft.value).trim(); if (!value || sending.value) return; messages.value.push({ id: `${Date.now()}-q`, role: 'user', content: value }); draft.value = ''; sending.value = true; receiving.value = false; await scrollBottom(); try { if (dataMode.value) { const result = (await sendDataQuery(value)).data; messages.value.push({ id: `${Date.now()}-a`, role: 'assistant', content: result.answer, source: result.model === 'llm' ? 'ai' : 'fallback', data: { sql: result.sql, columns: result.columns, rows: (result.rows || []).map((row) => Object.fromEntries(row.map((v, i) => [String(i), v]))), row_count: result.row_count } }) } else { const history = messages.value.slice(-12).map((item) => ({ role: item.role, content: item.content })); let live = null; const ensureLive = () => { if (!live) { messages.value.push({ id: `${Date.now()}-a`, role: 'assistant', content: '', source: 'ai', knowledge: [] }); live = messages.value[messages.value.length - 1]; receiving.value = true } }; const typer = createTyper((chunk) => { ensureLive(); live.content += chunk; const box = messageBox.value; if (!box || box.scrollHeight - box.scrollTop - box.clientHeight < 90) scrollBottom() }); const result = await streamKnowledgeChat(value, history.slice(0, -1), { onMeta: (meta) => { runtime.value = meta.runtime || runtime.value }, onDelta: (t) => typer.push(t) }); typer.flush(); ensureLive(); live.source = result.source; if (result.knowledge?.length) live.knowledge = result.knowledge; if (!live.content.trim()) live.content = result.error || '（AI 未返回内容，请稍后重试）' } } catch (error) { ElMessage.error(error.message || '对话请求失败'); messages.value.push({ id: `${Date.now()}-e`, role: 'assistant', content: error.message || '对话服务暂时不可用，请稍后重试。' }) } finally { sending.value = false; receiving.value = false; await scrollBottom() } }
</script>

