: var(--ink-2); background: var(--surface); cursor: pointer; text-align: left; transition: all .2s; }.suggestions button:hover, .quick-bar button:hover { border-color: var(--brand); color: var(--brand); transform: translateY(-1px); }.message { display: flex; gap: 11px; margin-bottom: 24px; }.message.user { flex-direction: row-reverse; }.message-avatar { display: grid; place-items: center; flex: none; width: 30px; height: 30px; border-radius: 9px; color: #fff; background: var(--violet); font-size: 11px; font-weight: 700; }.message.user .message-avatar { background: var(--brand); }.message-content { max-width: 80%; }.message.user .message-content { text-align: right; }.message-meta { margin-bottom: 6px; color: var(--muted); font-size: 12px; }.message-meta small { margin-left: 6px; color: var(--faint); }.message-text { display: inline-block; padding: 12px 14px; border-radius: 4px 14px 14px 14px; color: var(--ink-2); background: var(--el-fill-color); font-size: 14px; line-height: 1.7; white-space: pre-wrap; text-align: left; }.message.user .message-text { border-radius: 14px 4px 14px 14px; color: #fff; background: var(--brand); }.citation { margin-top: 8px; color: var(--muted); font-size: 11px; text-align: left; }.typing { display: flex; gap: 4px; padding: 14px; border-radius: 4px 14px 14px 14px; background: var(--el-fill-color); }.typing i { width: 6px; height: 6px; border-radius: 50%; background: var(--faint); animation: blink 1s infinite; }.typing i:nth-child(2) { animation-delay: .15s; }.typing i:nth-child(3) { animation-delay: .3s; }@keyframes blink { 0%, 80%, 100% { opacity: .3; } 40% { opacity: 1; } }.quick-bar { display: flex; align-items: center; gap: 8px; padding: 10px 20px; border-top: 1px solid var(--line); color: var(--muted); font-size: 12px; overflow: auto; }.quick-bar button { flex: none; padding: 6px 10px; font-size: 12px; }.mode-switch { display: flex; align-items: center; gap: 6px; margin-left: auto; color: var(--ink-2); font-size: 12px; white-space: 