k; }.context-alert strong { font-size: 12px; }.context-alert small { margin-top: 3px; color: var(--muted); font-size: 11px; }.context-section ul { padding-left: 17px; margin: 0; color: var(--muted); font-size: 12px; line-height: 2; }
@media (max-width: 900px) { .chat-head { align-items: flex-start; flex-direction: column; gap: 12px; }.chat-layout { grid-template-columns: 1fr; }.context-card { min-height: auto; }.suggestions { grid-template-columns: 1fr; } }
